 box=d.xpos[s.env.obj_body_id['container']].copy();si=m.site('gripper0_right_grip_site').id
 def op():return d.xpos[s.env.obj_body_id['obj']].copy()
 def hp():return d.site_xpos[si].copy()
 def move(p=None,h=None,n=60):
  a=s.targets.copy();start=a.copy()
  if p is not None:a[:3]=R.T@(np.array(p)-t)
  if h is not None:a[12:18]=h
  for i in range(n):s.step(start+(a-start)*min(1,(i+1)/max(1,n-20)))
