 move(target,n=steps)
 released_at=op().copy()
 move(h=np.zeros(6),n=release_steps)
 move([3.02,-2.02,1.34],n=120)
 result=dict(name=name,success=s.success,steps=len(s.actions),distance=float(np.linalg.norm(op()[:2]-box[:2])),release_height=float(released_at[2]),box_upright=float(d.xmat[s.env.obj_body_id['container']].reshape(3,3)[2,2]))
