import numpy as np,casa_tool
s=casa_tool.Session('/app/instance.npz');A=np.load('/app/output/pitch_30.npz')['actions']

def trial(name,mode='all',opening=50,pause=20,retreat=100):
 s.replay(A[:870]);m,d=s.model,s.data;bi=m.body('robot0_base').id;R=d.xmat[bi].reshape(3,3).copy();t=d.xpos[bi].copy()
 def move(p=None,h=None,n=60):
  start=s.targets.copy();a=start.copy()
  if p is not None:a[:3]=R.T@(np.array(p)-t)
  if h is not None:a[12:18]=h
  for i in range(n):s.step(start+(a-start)*min(1,(i+1)/max(1,n-pause)))
 if mode=='thumb':
  h=s.targets[12:18].copy();h[4:]=0;move(h=h,n=opening);move(h=np.zeros(6),n=opening)
 elif mode=='fingers':
  h=s.targets[12:18].copy();h[:4]=0;move(h=h,n=opening);move(h=np.zeros(6),n=opening)
 elif mode=='thumbflex':
  h=s.targets[12:18].copy();h[4]=0;move(h=h,n=opening);move(h=np.zeros(6),n=opening)
 elif mode=='thumbrot':
  h=s.targets[12:18].copy();h[5]=0;move(h=h,n=opening);move(h=np.zeros(6),n=opening)
 elif mode=='negative':move(h=[-.5]*6,n=opening)
