import logging,json
logging.getLogger().setLevel(logging.ERROR)
import numpy as np,casa_tool
from scipy.spatial.transform import Rotation
s=casa_tool.Session('/app/instance.npz');A=np.load('/app/output/scale_linear_50.npz')['actions']

def trial(name,offset=(.13,.09,.30),angle=30,aim_steps=80,open_steps=35,retreat_steps=60,prefix=355):
 s.replay(A[:prefix]);m,d=s.model,s.data;bi=m.body('robot0_base').id;R=d.xmat[bi].reshape(3,3).copy();t=d.xpos[bi].copy();b=d.xpos[s.env.obj_body_id['container']].copy()
 def op():return d.xpos[s.env.obj_body_id['obj']].copy()
 def move(p=None,r=None,h=None,n=60):
  start=s.targets.copy();a=start.copy()
  if p is not None:a[:3]=R.T@(np.array(p)-t)
  if r is not None:a[3:6]=r
  if h is not None:a[12:18]=h
  for i in range(n):s.step(start+(a-start)*min(1,(i+1)/max(1,n-10)))
 carried=op()[2]>1.1;rot=Rotation.from_matrix(R.T@Rotation.from_euler('x',angle,degrees=True).as_matrix()@np.diag([1.,-1.,-1.])).as_rotvec();move(b+np.array(offset),rot,n=aim_steps);held=op()[2]>1.1;release=op().copy();move(h=np.zeros(6),n=open_steps);move([3.02,-2.02,1.34],n=retreat_steps)
 clear=[]
 for arm in ['right','left']:
  hp=d.site_xpos[m.site('gripper0_'+arm+'_grip_site').id];clear.extend(float(np.linalg.norm(hp-d.xpos[s.env.obj_body_id[o]])) for o in ['obj','container'])
 result=dict(name=name,success=s.success,carried=bool(carried),held=bool(held),steps=len(s.actions),distance=float(np.linalg.norm(op()[:2]-b[:2])),clearance=min(clear),release=release.tolist(),offset=list(offset),angle=angle,aim_steps=aim_steps,open_steps=open_steps,retreat_steps=retreat_steps,prefix=prefix)
 print('RESULT',json.dumps(result),flush=True)
 if s.success:s.save_trajectory(path='/app/output/'+name+'.npz')
 with open('/app/output/fast_aim_results.jsonl','a')as f:f.write(json.dumps(result)+'\n')
 return result

if __name__=='__main__':
 for dx,dy in [(0,0),(-.02,0),(.02,0),(0,-.02),(0,.02),(-.02,-.02),(.02,.02),(-.02,.02),(.02,-.02)]:trial(f'fast_xy_{dx}_{dy}',(.13+dx,.09+dy,.30))
 for angle in [0,15,25,35,45,60]:trial(f'fast_angle_{angle}',angle=angle)
 for n in [40,50,60,100,120]:trial(f'fast_steps_{n}',aim_steps=n)
PY",max_output_tokens:1000}));text(await tools.write_stdin({session_id:22541,chars:"",yield_time_ms:30000,max_output_tokens:500}));text((await tools.exec_command({cmd:"tail -n 2 /app/output/time_scale_results.jsonl; tail -n 2 /app/output/release_results.jsonl; tail -n 2 /app/output/polish_results.jsonl",max_output_tokens:1900})).output);text(await tools.clock__curr_time({}));

