def trial(name,prefix=870,open_steps=15,open_settle=3,retreat=100,retreat_position=(3.02,-2.02,1.34)):
 s.replay(A[:prefix]);m,d=s.model,s.data;bi=m.body('robot0_base').id;R=d.xmat[bi].reshape(3,3).copy();t=d.xpos[bi].copy()
 def move(p=None,h=None,n=60,settle=20):
  start=s.targets.copy();a=start.copy()
  if p is not None:a[:3]=R.T@(np.array(p)-t)
  if h is not None:a[12:18]=h
  for i in range(n):s.step(start+(a-start)*min(1,(i+1)/max(1,n-settle)))
 release=d.xpos[s.env.obj_body_id['obj']].copy();move(h=np.zeros(6),n=open_steps,settle=open_settle);move(retreat_position,n=retreat)
 op=d.xpos[s.env.obj_body_id['obj']];box=d.xpos[s.env.obj_body_id['container']];clear=[]
 for arm in ['right','left']:
  hp=d.site_xpos[m.site('gripper0_'+arm+'_grip_site').id];clear.extend(float(np.linalg.norm(hp-d.xpos[s.env.obj_body_id[o]])) for o in ['obj','container'])
 result=dict(name=name,success=s.success,steps=len(s.actions),prefix=prefix,open_steps=open_steps,open_settle=open_settle,retreat=retreat,distance=float(np.linalg.norm(op[:2]-box[:2])),clearance=min(clear),release=release.tolist())
 print('RESULT',json.dumps(result),flush=True)
 if s.success:s.save_trajectory(path='/app/output/'+name+'.npz')
 with open('/app/output/compact_open_results.jsonl','a')as f:f.write(json.dumps(result)+'\n')
 return result

if __name__=='__main__':
 for prefix in [720,740,760,780,800,820,840,850,860]:trial(f'early_open_{prefix}',prefix)
 for retreat in [40,50,60,70,80]:trial(f'quick_retreat_{retreat}',retreat=retreat)
